arguments.newText:
        # Cap at 1.0
        return min(1.0, combined_score)


def analyze_description_for_suspicious_content(description: str) -> bool:
    """
    Analyze a transaction description using OpenAI's GPT-4o to detect suspicious content.

    Args:
        description: The transaction description to analyze

    Returns:
        bool: True if the description seems suspicious, False otherwise
    """
    if not description or not description.strip():
        return False

    try:
        response = openai.chat.completions.create(
            model="gpt-4o",
            messages=[
                {
                    "role": "system",
                    "content": "You are a fraud detection assistant. Analyze transaction descriptions for suspicious patterns, unusual language, or potential indicators of fraudulent activity. Respond with ONLY 'true' if suspicious, 'false' if not suspicious."
                },
                {
                    "role": "user",
                    "content": f"Analyze this transaction description for suspicious content: '{description}'"
                }
            ],
            max_tokens=10,
            temperature=0.3
        )

        result = response.choices[0].message.content.strip().lower()
        is_suspicious = result in ['true', 'yes', '1']

        if is_suspicious:
            logger.warning(f"Suspicious description detected: {description[:100]}...")
        else:
            logger.debug(f"Description passed AI check: {description[:100]}...")

        return is_suspicious

    except Exception as e:
        logger.error(f"Error analyzing description with OpenAI: {str(e)}")
        # Fail-safe: if AI analysis fails, return False to avoid blocking legitimate transactions
        return False
